@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=DM+Sans:wght@400;500;600;700&family=Playfair+Display:wght@400;500;600;700&display=swap');
:root{--night:#171a31;--night2:#222641;--night3:#30344f;--paper:#f4efe5;--paper2:#eae2d4;--ink:#25273a;--muted:#85818a;--gold:#c89e63;--gold2:#e0c18c;--rust:#b76d57;--sage:#8a9b82;--line:rgba(38,39,58,.12);--serif:'Playfair Display',Georgia,serif;--sans:'DM Sans',Arial,sans-serif;--mono:'DM Mono',monospace}
*{box-sizing:border-box}body{margin:0;background:#e8e2d7;color:var(--ink);font-family:var(--sans);font-size:14px}button{font:inherit}button:focus-visible{outline:2px solid var(--gold);outline-offset:3px}.shell{min-height:100vh;display:grid;grid-template-columns:244px minmax(0,1fr)}
.sidebar{background:var(--night);color:#e9e5dc;padding:28px 20px 20px;display:flex;flex-direction:column;min-height:100vh;position:sticky;top:0;height:100vh}.brand{display:flex;align-items:center;gap:12px;padding:2px 6px 29px}.sigil{width:37px;height:37px;border:1px solid var(--gold);border-radius:50%;display:grid;place-items:center;color:var(--gold2);font:20px var(--serif);position:relative}.sigil:after{content:'';position:absolute;inset:5px;border:1px solid rgba(200,158,99,.38);border-radius:50%}.brand-name{font:600 16px var(--serif);letter-spacing:.03em}.brand-sub{display:block;color:#a6a2a3;font:9px var(--mono);letter-spacing:.17em;text-transform:uppercase;margin-top:3px}.side-label,.eyebrow{font:10px var(--mono);letter-spacing:.16em;text-transform:uppercase}.side-label{color:#7d8197;padding:15px 10px 9px}.nav{display:grid;gap:5px}.nav-button{background:transparent;color:#a8aab8;border:0;text-align:left;padding:12px;display:flex;align-items:center;gap:12px;border-radius:4px;cursor:pointer;transition:.2s}.nav-button span{font-size:17px;width:18px;text-align:center}.nav-button:hover,.nav-button.active{background:#292d48;color:#f5eee1}.nav-button.active{box-shadow:inset 2px 0 var(--gold)}.nav-button i{font:10px var(--mono);font-style:normal;margin-left:auto;border:1px solid #494b60;border-radius:20px;padding:2px 6px}.sidebar-card{margin-top:auto;border-top:1px solid #34374d;border-bottom:1px solid #34374d;padding:8px 8px 18px}.sidebar-card p{font:italic 14px/1.65 var(--serif);color:#c6c2bf;margin:9px 0}.sidebar-card>span{font:10px var(--mono);color:var(--gold)}.side-bottom{display:flex;gap:10px;align-items:center;padding:18px 5px 0}.moon{font:25px var(--serif);color:var(--gold2)}.side-bottom strong{display:block;font:12px var(--serif);font-weight:500}.side-bottom small{display:block;color:#8f91a1;font:9px var(--mono);margin-top:4px}.side-bottom button{margin-left:auto;background:none;color:#9798a7;border:1px solid #484b62;border-radius:50%;height:25px;width:25px;cursor:pointer}
.main{min-width:0;padding:0 40px;display:flex;flex-direction:column}.topbar{display:flex;justify-content:space-between;align-items:center;padding:30px 0 24px;border-bottom:1px solid rgba(40,39,58,.12)}.eyebrow{color:#938b82;font-size:9px}.topbar h1{font:500 28px var(--serif);margin:4px 0 0;letter-spacing:-.02em}.top-right{display:flex;gap:23px;align-items:center}.save-state{font-size:11px;color:#777681;display:flex;align-items:center;gap:8px}.save-dot{background:#879b79;width:6px;height:6px;border-radius:50%;box-shadow:0 0 0 3px #879b7922}.reset-button{background:none;border:0;color:#7f7a7a;font-size:11px;cursor:pointer}.reset-button span{font-size:17px;margin-left:4px}.game-wrap{padding:26px 0 28px;flex:1}.footer{border-top:1px solid rgba(40,39,58,.12);padding:14px 0 17px;display:flex;justify-content:space-between;color:#99928b;font:9px var(--mono);letter-spacing:.1em}.footer b{color:var(--gold);padding:0 4px}
.dashboard{display:grid;grid-template-columns:minmax(0,1.55fr) minmax(280px,.8fr);gap:20px}.column{display:grid;align-content:start;gap:18px}.panel{background:var(--paper);border:1px solid rgba(53,45,43,.08);box-shadow:0 7px 24px #30291e0a}.panel-head{padding:17px 20px 13px;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between}.panel-title{font:500 17px var(--serif)}.panel-kicker{font:9px var(--mono);color:#9a9188;letter-spacing:.14em;text-transform:uppercase}.case-panel{overflow:hidden}.case-hero{position:relative;background:var(--night2);color:#eee9e0;min-height:175px;padding:24px 25px 22px;overflow:hidden}.case-hero:before,.case-hero:after{content:'';position:absolute;border:1px solid rgba(214,182,130,.18);border-radius:50%;width:210px;height:210px;right:-28px;top:-104px}.case-hero:after{width:150px;height:150px;right:2px;top:-73px}.hero-symbol{position:absolute;right:31px;top:19px;color:#d4ad71;font:70px/1 var(--serif);opacity:.73}.hero-label{position:relative;color:#d3b57f;font:9px var(--mono);letter-spacing:.17em;text-transform:uppercase}.case-hero h2{position:relative;font:500 27px var(--serif);margin:10px 0 5px}.case-subtitle{position:relative;color:#aeb0bc;font:11px var(--mono);letter-spacing:.06em}.case-story{padding:17px 25px 10px;font:15px/1.65 var(--serif);color:#4d4a51;max-width:680px;min-height:71px}.case-meta{margin:0 25px 13px;display:flex;gap:7px;flex-wrap:wrap}.tag{border:1px solid #ded5c7;color:#81796f;border-radius:20px;padding:5px 9px;font:9px var(--mono);letter-spacing:.04em}.tag.gold{border-color:#e4d1ad;color:#9e7848;background:#c89e6310}.choices{display:grid;grid-template-columns:1fr 1fr;gap:10px;padding:0 20px 19px}.choice{position:relative;text-align:left;padding:13px 14px 12px;border:1px solid #ded8ce;background:#f9f6f0;color:var(--ink);cursor:pointer;transition:.18s;min-height:102px}.choice:hover:not(:disabled){border-color:var(--gold);transform:translateY(-2px);box-shadow:0 5px 14px #3328180b}.choice:disabled{opacity:.48;cursor:not-allowed}.choice-title{font:500 14px var(--serif);display:block;padding-right:25px}.choice-copy{font-size:11px;line-height:1.45;color:#79747a;display:block;margin:6px 0 10px}.choice-foot{display:flex;align-items:center;justify-content:space-between;font:9px var(--mono);color:#a17a45}.choice-mark{position:absolute;right:12px;top:12px;color:#c5a16b;font-size:15px}.unavailable{font:10px var(--mono);color:#ad6251!important}.case-complete{padding:18px 25px 22px;color:#71806a;font:13px var(--serif)}
.day-panel{background:var(--night);color:#ece7df;padding:19px 20px}.day-top{display:flex;justify-content:space-between;align-items:flex-start}.day-label{font:9px var(--mono);color:#9b9dae;letter-spacing:.15em;text-transform:uppercase}.day-number{font:500 25px var(--serif);margin-top:3px}.day-number span{color:#8f91a3;font-size:15px}.weather{font-size:25px;color:var(--gold2)}.day-progress{display:flex;gap:5px;margin:17px 0 16px}.day-progress span{height:3px;background:#3d4056;flex:1}.day-progress span.done{background:var(--gold)}.action-row{display:flex;justify-content:space-between;align-items:center}.ap-label{font:10px var(--mono);color:#b4b3bd}.ap-dots{display:flex;gap:5px}.ap-dots span{width:7px;height:7px;border-radius:50%;background:#43465c}.ap-dots span.on{background:var(--gold2)}.end-button{margin-top:17px;width:100%;border:1px solid #8e744e;background:#c39b60;color:#201f2b;padding:10px 12px;font:500 11px var(--mono);letter-spacing:.06em;cursor:pointer;transition:.2s}.end-button:hover{background:#dfbd82}.end-button:disabled{opacity:.45;cursor:not-allowed}.case-list{background:var(--paper)}.case-list .panel-head{padding-bottom:11px}.resident-row{display:flex;align-items:center;gap:11px;padding:11px 16px;border-bottom:1px solid var(--line);cursor:pointer;transition:.15s}.resident-row:last-child{border-bottom:0}.resident-row:hover,.resident-row.selected{background:#eee8dc}.portrait{width:33px;height:33px;border-radius:50%;display:grid;place-items:center;font:17px var(--serif);background:#d9d4c7;color:#575876;flex:none}.portrait.coral{background:#e8d2c2;color:#995e53}.portrait.sage{background:#d4dbce;color:#68735e}.resident-name{font:13px var(--serif)}.resident-need{font:9px var(--mono);color:#918b87;margin-top:3px}.resident-status{margin-left:auto;color:#b1804d;font:9px var(--mono)}.resident-status.done{color:#778670}.climate{padding-bottom:15px}.climate .panel-head{border:0}.climate-row{display:grid;grid-template-columns:81px 1fr 29px;align-items:center;gap:9px;margin:11px 19px}.climate-name{font:10px var(--mono);color:#77747a}.meter{height:5px;background:#e4ddd2;border-radius:5px;overflow:hidden}.meter span{display:block;height:100%;background:#aa8b64;border-radius:5px;transition:width .5s}.climate-row:nth-child(3) .meter span{background:#83829a}.climate-row:nth-child(4) .meter span{background:#a77364}.climate-row:nth-child(5) .meter span{background:#89977f}.climate-value{font:9px var(--mono);color:#938d84;text-align:right}.climate-note{margin:13px 19px 0;padding-top:12px;border-top:1px solid var(--line);font:italic 12px/1.5 var(--serif);color:#858079}
.resources{display:flex;gap:8px}.resource{border:1px solid #41445a;background:#20243d;border-radius:3px;padding:5px 7px;color:#d8d1c5;font:9px var(--mono);white-space:nowrap}.resource b{color:var(--gold2);font-weight:400;margin-right:3px}.log-panel{padding-bottom:5px}.log-entry{display:grid;grid-template-columns:35px 1fr;gap:7px;padding:10px 17px;border-bottom:1px solid var(--line);font:11px/1.5 var(--sans);color:#6f6b72}.log-entry:last-child{border:0}.log-day{font:9px var(--mono);color:#b08a55;padding-top:2px}.empty-log{padding:17px;font:italic 13px var(--serif);color:#938d84}
.view-page{max-width:1060px;margin:0 auto}.view-intro{margin:7px 0 20px;color:#77737a;font:15px/1.6 var(--serif);max-width:660px}.resident-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:13px}.resident-card{background:var(--paper);padding:19px;border:1px solid var(--line);cursor:pointer;transition:.18s}.resident-card:hover{transform:translateY(-2px);border-color:#cdb78f}.resident-card-top{display:flex;gap:12px;align-items:center}.resident-card h3{margin:0;font:18px var(--serif)}.resident-card .need{font:9px var(--mono);color:#938b82;margin-top:4px}.resident-card p{font:13px/1.55 var(--serif);color:#716d71;margin:13px 0}.resident-card-foot{display:flex;justify-content:space-between;color:#9b784d;font:9px var(--mono)}.archive-list{display:grid;gap:9px}.archive-item{display:flex;gap:17px;background:var(--paper);padding:18px;border:1px solid var(--line)}.archive-day{font:10px var(--mono);color:#ad8956;min-width:57px}.archive-item h3{font:17px var(--serif);font-weight:500;margin:0}.archive-item p{margin:5px 0 0;color:#77737a;font:12px/1.5 var(--sans)}.archive-item .outcome{font:10px var(--mono);color:#71806a;margin-top:8px}.archive-empty{text-align:center;background:var(--paper);padding:40px;font:italic 16px var(--serif);color:#8e8982}
.overlay{position:fixed;inset:0;background:#131629c9;display:grid;place-items:center;padding:20px;z-index:5;backdrop-filter:blur(4px)}.modal{width:min(500px,100%);background:var(--paper);padding:34px 35px 30px;text-align:center;position:relative;box-shadow:0 22px 80px #080a16aa}.modal-sigil{font:36px var(--serif);color:var(--gold);margin-bottom:11px}.modal h2{font:500 29px var(--serif);margin:0 0 11px}.modal p{font:14px/1.65 var(--serif);color:#767078;margin:0 auto 20px;max-width:390px}.modal-score{font:10px var(--mono);letter-spacing:.1em;color:#9c794c;margin:15px}.modal-button{background:var(--night2);color:var(--paper);border:0;padding:12px 23px;font:10px var(--mono);letter-spacing:.1em;cursor:pointer}.toast{position:fixed;bottom:25px;right:25px;padding:11px 15px;background:#242741;color:#efe9dd;font:11px var(--mono);z-index:8;opacity:0;transform:translateY(8px);transition:.25s;pointer-events:none}.toast.show{opacity:1;transform:translateY(0)}
@media(max-width:1050px){.main{padding:0 25px}.dashboard{grid-template-columns:minmax(0,1.25fr) minmax(255px,.8fr)}.resources{gap:4px}.resource{padding:5px}.sidebar{width:auto}.shell{grid-template-columns:215px minmax(0,1fr)}}
@media(max-width:760px){.shell{display:block}.sidebar{position:relative;height:auto;min-height:0;padding:12px 16px;display:flex;flex-direction:row;align-items:center;gap:12px}.brand{padding:0;flex:1}.sigil{height:32px;width:32px}.brand-name{font-size:14px}.brand-sub{font-size:8px}.sidebar>.side-label,.sidebar-card,.side-bottom{display:none}.nav{display:flex;gap:2px}.nav-button{padding:9px 10px;font-size:0;gap:0}.nav-button span{font-size:16px}.nav-button i{display:none}.main{padding:0 17px}.topbar{padding:20px 0 17px}.topbar h1{font-size:24px}.eyebrow{font-size:8px}.top-right{gap:9px}.save-state{font-size:0}.save-dot{height:7px;width:7px}.reset-button{font-size:10px}.game-wrap{padding:17px 0}.dashboard{grid-template-columns:1fr;gap:13px}.column{gap:13px}.case-hero{min-height:152px;padding:19px 19px}.case-hero h2{font-size:23px}.hero-symbol{font-size:55px;right:20px}.case-story{padding:15px 19px 8px;font-size:14px}.case-meta{margin:0 19px 12px}.choices{padding:0 13px 14px;gap:7px}.choice{padding:11px 10px;min-height:120px}.choice-title{font-size:13px}.choice-copy{font-size:10px}.panel-head{padding:14px 16px 11px}.panel-title{font-size:16px}.resources{flex-wrap:wrap;justify-content:flex-end;max-width:150px}.resource{font-size:8px}.day-panel{padding:16px}.footer{font-size:8px}.footer span:last-child{display:none}.resident-grid{grid-template-columns:1fr}.view-intro{font-size:14px}.archive-item{padding:14px;gap:8px}.archive-day{min-width:48px;font-size:9px}}
@media(max-width:390px){.main{padding:0 12px}.brand{gap:7px}.brand-name{font-size:13px}.brand-sub{letter-spacing:.1em}.nav-button{padding:8px}.choices{grid-template-columns:1fr}.choice{min-height:0}.topbar h1{font-size:22px}}

const episodes=[
 [{name:'Mara Venn',role:'The overfull mask',glyph:'◉',need:'PERSONA · BOUNDARIES',story:'Mara arrives with a list of everyone she has ever disappointed. “If I stop being useful,” she asks, “will there be anything left of me?” Her hands are still folded neatly in her lap.',tags:['The Caretaker','A borrowed face'],choices:[{title:'Ask what she wants',copy:'Let the polished answer wait. Make room for a private wish.',cost:0,currency:'ink',effects:{persona:7,anima:4,trust:3,insight:1},result:'Mara names a wish that belongs to her alone.'},{title:'Honor the mask, gently',copy:'Thank the role that kept her safe, then loosen its ties.',cost:1,currency:'ink',effects:{persona:3,shadow:3,trust:4},result:'Mara leaves with permission to be more than useful.'}]},
 {name:'Ivo Calder',role:'A locked room',glyph:'⌁',need:'SHADOW · ANGER',story:'Ivo has not slept since his brother left. He calls his anger “unseemly” and keeps it tucked beneath an immaculate coat. The room seems to grow colder when he smiles.',tags:['The Exile','A disowned feeling'],choices:[{title:'Give anger a chair',copy:'Meet the feeling without asking it to leave.',cost:0,currency:'ink',effects:{shadow:8,trust:3,insight:1},result:'Ivo listens to his anger; it turns out to be guarding grief.'},{title:'Read the dream aloud',copy:'Follow the black dog in last night’s dream.',cost:1,currency:'ink',effects:{shadow:5,child:3,trust:4},result:'The black dog leads Ivo toward a memory he can finally hold.'}]},
 {name:'Noor Bell',role:'The bright exile',glyph:'☼',need:'ANIMA · LONGING',story:'Noor is admired for her certainty. In the greenhouse she admits she has forgotten what she loves. “Everything I choose,” she says, “is a choice someone will approve of.”',tags:['The Seeker','A quiet longing'],choices:[{title:'Walk without a destination',copy:'Invite the body to lead where the mind cannot.',cost:0,currency:'ink',effects:{anima:8,persona:-2,trust:3},result:'Noor finds herself lingering beside a wild, unlabelled flower.'},{title:'Listen for the small voice',copy:'Follow the memory that arrives before explanation.',cost:1,currency:'ink',effects:{anima:4,child:4,insight:1,trust:3},result:'A childhood song returns, imperfect and entirely hers.'}]},
 {name:'Eli Ash',role:'The child at the gate',glyph:'✳',need:'CHILD · PLAY',story:'Eli, a retired schoolmaster, has brought a wooden boat he made at nine. He cannot explain why he kept it. He laughs once, then looks embarrassed by the sound.',tags:['The Innocent','A door left open'],choices:[{title:'Make something useless',copy:'Set the timetable aside. Let the hands remember.',cost:0,currency:'ink',effects:{child:8,anima:3,trust:3},result:'Eli makes a crooked second boat and gives it no purpose.'},{title:'Ask the boat where it sails',copy:'Let the image speak in its own strange language.',cost:1,currency:'ink',effects:{child:4,shadow:3,insight:1,trust:4},result:'The boat carries Eli toward a grief he had mistaken for duty.'}]},
 {name:'Ada Rook',role:'A perfect garden',glyph:'❋',need:'PERSONA · CONTROL',story:'Ada has arranged every stone in her garden. One stubborn patch of nettles refuses her plan. She speaks of it as a failure, though she visits it every morning.',tags:['The Steward','A necessary wildness'],choices:[{title:'Leave one corner untended',copy:'Invite the unplanned to have a place in the garden.',cost:0,currency:'ink',effects:{persona:-3,shadow:5,anima:3,trust:4},result:'Ada discovers a small violet among the nettles.'},{title:'Ask what the nettles protect',copy:'Approach resistance as a messenger, not an enemy.',cost:1,currency:'ink',effects:{shadow:6,insight:1,trust:3},result:'The nettles mark the place where Ada buried her own ambition.'}]},
 {name:'Samir Vale',role:'The borrowed voice',glyph:'◌',need:'ANIMA · AUTHENTICITY',story:'Samir is a gifted pianist who can play any request except his own. He has spent a lifetime sounding like the person the room needs. Today, he brings no sheet music.',tags:['The Artist','A note unsung'],choices:[{title:'Let silence have a measure',copy:'Stay with the pause before the expected performance.',cost:0,currency:'ink',effects:{anima:7,persona:-2,trust:4},result:'Samir finds one note that feels like a window opening.'},{title:'Play the unfinished thing',copy:'Offer the imperfect fragment, without apology.',cost:1,currency:'ink',effects:{anima:4,child:4,insight:1,trust:3},result:'The unfinished melody makes the room feel more honest.'}]},
 {name:'June Holloway',role:'The old compass',glyph:'☽',need:'SHADOW · MEANING',story:'June has just retired. Without the title on her door, she feels like a house with its sign taken down. She asks if a life can have a second beginning without pretending the first did not happen.',tags:['The Wanderer','A threshold'],choices:[{title:'Map what remains',copy:'Name the values that outlive a role.',cost:0,currency:'ink',effects:{shadow:4,anima:4,trust:4,insight:1},result:'June finds that care, not achievement, was the thread all along.'},{title:'Sit at the threshold',copy:'Let the in-between be a place, not a problem.',cost:1,currency:'ink',effects:{shadow:5,child:3,trust:4},result:'June leaves the door ajar. She does not need to name the next room yet.'}]},
];
const names=['The Persona','The Shadow','The Anima','The Child'];
const keys=['persona','shadow','anima','child'];
const fresh=()=>({day:1,ap:3,ink:5,trust:58,insight:0,stats:{persona:48,shadow:35,anima:50,child:43},selected:0,view:'house',done:false,log:[{day:1,text:'You unlock the House. Seven days, and the courage to look inward.'}],archive:[],cases:[]});
let s;try{s={...fresh(),...JSON.parse(localStorage.getItem('unseen-house-save')||'{}')};s.stats={...fresh().stats,...s.stats};}catch{s=fresh()}
let toastTimer;
function makeCases(){const ds=episodes[(s.day-1)%episodes.length], other=episodes[(s.day)%episodes.length];s.cases=[{...structuredClone(ds),id:`${s.day}-0`,status:'open'},{...structuredClone(other),id:`${s.day}-1`,status:'open'}];s.selected=0;}
if(!s.cases?.length&&!s.done)makeCases();
function save(){try{localStorage.setItem('unseen-house-save',JSON.stringify(s));document.querySelector('#saveLabel').textContent='Your progress is kept';}catch{}}
function clamp(v){return Math.max(0,Math.min(100,v))}
function addLog(text){s.log.unshift({day:s.day,text});s.log=s.log.slice(0,24)}
function showToast(t){let el=document.querySelector('#toast');el.textContent=t;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2200)}
function currentCase(){return s.cases[s.selected]||s.cases.find(c=>c.status==='open')||s.cases[0]}
function render(){const root=document.querySelector('#app');document.querySelector('#pageTitle').textContent=s.view==='house'?'The House':s.view==='residents'?'Residents':'Chronicle';document.querySelectorAll('.nav-button').forEach(b=>b.classList.toggle('active',b.dataset.view===s.view));document.querySelector('#residentCount').textContent=String(s.cases.filter(c=>c.status==='open').length).padStart(2,'0');if(s.view==='house')root.innerHTML=house();else if(s.view==='residents')root.innerHTML=residents();else root.innerHTML=chronicle();save();}
function climate(){return `<section class="panel climate"><div class="panel-head"><div><div class="panel-kicker">The inner weather</div><div class="panel-title">Four rooms of the psyche</div></div><div class="panel-kicker">INTEGRATION</div></div>${keys.map((k,i)=>`<div class="climate-row"><span class="climate-name">${names[i]}</span><div class="meter"><span style="width:${s.stats[k]}%"></span></div><span class="climate-value">${s.stats[k]}</span></div>`).join('')}<div class="climate-note">Wholeness is not perfection. It is a conversation between all the rooms.</div></section>`}
function residentRows(){return `<section class="panel case-list"><div class="panel-head"><div><div class="panel-kicker">Today’s arrivals</div><div class="panel-title">At the door</div></div><span class="panel-kicker">${s.cases.filter(c=>c.status==='open').length} WAITING</span></div>${s.cases.map((c,i)=>`<div class="resident-row ${s.selected===i?'selected':''}" data-case="${i}"><div class="portrait ${i?'coral':''}">${c.glyph}</div><div><div class="resident-name">${c.name}</div><div class="resident-need">${c.need}</div></div><span class="resident-status ${c.status==='resolved'?'done':''}">${c.status==='resolved'?'HEARD':'WAITING'}</span></div>`).join('')}</section>`}
function house(){const c=currentCase();let caseBody=c.status==='resolved'?`<div class="case-complete">✦ &nbsp;This conversation has been held. You listened well.</div>`:`<div class="case-story">${c.story}</div><div class="case-meta">${c.tags.map(t=>`<span class="tag">${t}</span>`).join('')}<span class="tag gold">1 time</span></div><div class="choices">${c.choices.map((o,i)=>{const blocked=s.ap<1||s.ink<o.cost;return `<button class="choice" data-choice="${i}" ${blocked?'disabled':''}><span class="choice-mark">${i?'↗':'✳'}</span><span class="choice-title">${o.title}</span><span class="choice-copy">${o.copy}</span><span class="choice-foot"><span>${o.cost?`◈ ${o.cost} ink`:'◈ no ink'}</span><span>−1 hour</span></span></button>`}).join('')}</div>`;
