function chronicle(){return `<div class="view-page"><div class="panel-kicker">What the House remembers</div><p class="view-intro">Small changes are still changes. Here are the moments you have chosen to keep.</p><div class="archive-list">${s.archive.length?s.archive.map(a=>`<article class="archive-item"><div class="archive-day">DAY ${a.day}</div><div><h3>${a.name}</h3><p>${a.story}</p><div class="outcome">✦ &nbsp;${a.result}</div></div></article>`).join(''):'<div class="archive-empty">The pages are blank, for now. Listen, and the story will come.</div>'}</div><section class="panel log-panel" style="margin-top:20px"><div class="panel-head"><div><div class="panel-kicker">Daily notes</div><div class="panel-title">The House, in brief</div></div></div>${s.log.map(e=>`<div class="log-entry"><span class="log-day">D.${e.day}</span><span>${e.text}</span></div>`).join('')}</section></div>`}
function act(type){if(s.ap<1)return;if(type==='dream'){if(s.ink<1){showToast('You need one ink for the journal.');return}s.ink--;s.insight++;s.stats.shadow=clamp(s.stats.shadow+4);s.stats.anima=clamp(s.stats.anima+1);addLog('You keep a dream journal. An image from the night stays with you.');showToast('A dream is given a little room.')}else{s.trust=clamp(s.trust+4);s.stats.child=clamp(s.stats.child+2);s.stats.anima=clamp(s.stats.anima+1);addLog('You tend the courtyard. The House feels a little more like home.');showToast('The courtyard is tended.')}s.ap--;render()}
function treat(choice){const c=currentCase(),o=c.choices[choice];if(!o||c.status!=='open'||s.ap<1||s.ink<o.cost)return;s.ink-=o.cost;s.ap--;Object.entries(o.effects).forEach(([k,v])=>{if(k==='trust')s.trust=clamp(s.trust+v);else if(k==='insight')s.insight+=v;else s.stats[k]=clamp(s.stats[k]+v)});c.status='resolved';s.archive.unshift({day:s.day,name:c.name,story:c.story,result:o.result});addLog(`${c.name}: ${o.result}`);let next=s.cases.findIndex(x=>x.status==='open');if(next>=0)s.selected=next;showToast('A story has been heard.');render()}
function closeDay(){if(s.day>=7){s.cases.filter(c=>c.status==='open').forEach(c=>s.trust=clamp(s.trust-2));s.done=true;s.view='chronicle';addLog('The first season closes. The House is still becoming.');render();ending();return}const missed=s.cases.filter(c=>c.status==='open');if(missed.length){s.trust=clamp(s.trust-missed.length*2);addLog(`${missed.length} resident${missed.length>1?'s':''} wait for another day. You make a note to return.`)}else addLog('Both stories found a place to rest. The House grows quieter.');s.day++;s.ap=3;s.ink=Math.min(10,s.ink+2);makeCases();render();showToast('A new day begins. Two ink added.')}
function integration(){const vals=Object.values(s.stats);const spread=Math.max(...vals)-Math.min(...vals);return Math.round(Math.max(0,Math.min(100,100-spread*.48+s.trust*.12+s.insight*.55)))}
function overlay(title,text,button,handler,score=''){const el=document.createElement('div');el.className='overlay';el.innerHTML=`<section class="modal"><div class="modal-sigil">✳</div><div class="panel-kicker">THE UNSEEN HOUSE</div><h2>${title}</h2><p>${text}</p>${score?`<div class="modal-score">${score}</div>`:''}<button class="modal-button">${button}</button></section>`;el.querySelector('button').onclick=()=>{el.remove();handler?.()};document.body.appendChild(el)}
function ending(){overlay('A season, held gently',`You have spent seven days listening for what was asking to be heard. The work is not finished; it has become yours.`,`BEGIN ANOTHER SEASON`,()=>{s=fresh();makeCases();render()},`INTEGRATION &nbsp; ${integration()} / 100 &nbsp; · &nbsp; TRUST ${s.trust} &nbsp; · &nbsp; INSIGHT ${s.insight}`)}
function help(){overlay('How to tend the House','Each day gives you three hours. Choose a resident and a way to meet their story, or tend the House between consultations. Some approaches use ink; two ink return at each new day. Unheard residents wait, and trust may soften. Balance the four rooms of the psyche as you go. Your progress saves in this browser.','I UNDERSTAND')}
document.addEventListener('click',e=>{const nav=e.target.closest('.nav-button');if(nav){s.view=nav.dataset.view;render();return}if(e.target.closest('#helpBtn')){help();return}if(e.target.closest('#resetBtn')){overlay('Begin again?','A new season will set aside this one. Your current chronicle will be erased.','START A NEW SEASON',()=>{s=fresh();makeCases();render()});return}if(e.target.closest('#endDay')){closeDay();return}const card=e.target.closest('[data-case]');if(card){const idx=Number(card.dataset.case);if(Number.isInteger(idx)&&s.cases[idx]){s.selected=idx;s.view='house';render()}return}const choice=e.target.closest('[data-choice]');if(choice){treat(Number(choice.dataset.choice));return}const action=e.target.closest('[data-action]');if(action){act(action.dataset.action);return}});
if(s.done){s.view='chronicle';setTimeout(ending,150)}render();

